#ifndef CX_DEFINE_MQH
#define CX_DEFINE_MQH

/**
 * @file CXDefine.mqh
 * @brief XTA 시스템 전역 상수 및 열거형 정의 (Constants & Enums)
 * @details 상태 코드, 타입 정의, 고정값 등 정적 데이터 정의 모음
 */

//--- 시스템 규격 상수
#define SID_MAX_LENGTH       23
#define GID_MAX_LENGTH       16
#define COMMENT_MAX_LENGTH   31
#define DEFAULT_SLIPPAGE     30
#define MAX_SLIPPAGE         1000

//--- 로그 레벨 정의
enum ENUM_LOG_LEVEL {
    LOG_LVL_TRACE = 0,
    LOG_LVL_INFO  = 1,
    LOG_LVL_DEBUG = 2,
    LOG_LVL_WARN  = 3,
    LOG_LVL_ERROR = 4,
    LOG_LVL_OK    = 5
};

//--- 방향 정의 (dir)
enum ENUM_CX_DIRECTION {
    CX_DIR_NONE = 0,
    CX_DIR_BUY  = 1,
    CX_DIR_SELL = 2
};

//--- 주문 타입 정의
enum ENUM_CX_ORDER_TYPE {
    ORDER_LIMIT_TRAILING = 1,
    ORDER_LIMIT          = 2,
    ORDER_STOP           = 3,
    ORDER_MARKET         = 9
};

//--- XA_INTENT (UI/외부 명령 의도)
enum ENUM_XA_INTENT {
    XA_RAW           = 0,  // 초기 상태
    XA_ACTIVE        = 1,  // 활성화 (진입/청산 실행)
    XA_ARCHIVE_READY = 3   // 이관 대기 (App 마킹)
};

//--- XE_STATUS (EA 실행 상태)
enum ENUM_XE_STATUS {
    XE_READY            = 0,
    XE_PENDING_PLACED   = 1,
    XE_PENDING_REQ      = 2,  // [v9.9.2] 브로커 요청 전 DB 잠금 상태
    XE_IN_TRANSIT       = 3,  // [v9.9.2] 명령 송신 완료, 실물 동기화 대기 중
    XE_EXECUTED         = 10,
    XE_CLOSED_SIGNAL    = 20,
    XE_CLOSED_TP        = 21,
    XE_CLOSED_SL        = 23,
    XE_CLOSED_MANUAL    = 24,
    XE_VERIFY_ABS       = 25, // [v9.9.2] 청산 후 자산 소멸 검증 중
    XE_ERROR            = 99
};

//--- 세션 상태 및 시퀀스 단계 정의 (Sequence States)
enum ENUM_SESSION_STATE {
    SESSION_READY            = 0,
    STATE_ENTRY_TRANSIT      = 3,  // [v9.9.2] 주문 송신 후 브로커 응답 대기 상태
    STATE_ENTRY_VERIFY       = 4,  // [v9.9.2] 브로커 응답 후 실물 자산 존재 확인 상태
    STATE_ENTRY_TRAILING     = 5,
    SESSION_ACTIVE           = 10,
    STATE_SYNC_ALIGN         = 12, // [v9.9.2] DB와 터미널 간 강제 동기화 수행 상태
    STATE_EXIT_TRAILING      = 15,
    SESSION_LIQUIDATING      = 20,
    STATE_LIQUIDATING_TRANSIT = 21, // [v9.9.2] 청산 요청 후 브로커 응답 대기 상태
    STATE_EXIT_SWEEP         = 22,
    STATE_EXIT_VERIFY        = 23,
    SESSION_CLOSED           = 30,
    SESSION_ERROR            = 99
};

//--- Watcher 상태 및 시퀀스 단계 정의 (Watcher Sequence States)
enum ENUM_WATCHER_STATE {
    WATCHER_DISCOVERY      = 0,
    WATCHER_VALIDATION     = 1,
    WATCHER_BINDING        = 2,
    WATCHER_ERROR          = 99
};

//--- 시스템 이벤트 타입 정의
enum ENUM_CX_EVENT {
    EVENT_TICK          = 0,
    EVENT_TRANSACTION   = 1,
    EVENT_TIMER         = 2,
    EVENT_START         = 100,
    EVENT_INJECT        = 101
};

//--- Step 실행 공통 결과 (Generic Step Results)
#define STATE_UNCHANGED     -1

//--- 계산 스텝 결과 (Alpha Calculation Results)
enum ENUM_CALC_RESULT {
    CALC_NO_CHANGE = 0,
    CALC_MODIFIED  = 1
};

#endif

#ifndef IXTASK_MQH
#define IXTASK_MQH

#include <Object.mqh>
#include "ICXParam.mqh"
#include "ICXContext.mqh"

// Task 실행 결과 제어 상수
#define TASK_CONTINUE   -1  // 다음 태스크로 진행
#define TASK_BREAK      -2  // 현재 상태 유지하고 체인 실행 중단 (이번 틱 종료)
#define TASK_YIELD      -3  // 비차단 대기: 현재 상태를 유지하되 다음 틱에서 재시도

/**
 * @interface IXTask
 * @brief 시퀀스 스텝(Step) 내부에서 단일 책임을 수행하는 원자적 태스크 인터페이스
 * [v9.9.2] Hyper-Atomization을 위한 상태 제어 상수 및 프로퍼티 확장
 */
class IXTask : public CObject {
protected:
    int m_maxRetries;
    int m_retryCount;
    int m_timeoutSeconds;
    datetime m_startTime;

public:
    IXTask() : m_maxRetries(0), m_retryCount(0), m_timeoutSeconds(0), m_startTime(0) {}
    virtual ~IXTask() {}

    virtual string Name() = 0;

    /**
     * @brief 태스크 로직 실행
     * @return 양수(상태 코드): 즉시 해당 상태로 시퀀스 전이 발생
     *         TASK_CONTINUE: 다음 태스크로 흐름을 넘김
     *         TASK_BREAK: 태스크 체인 실행을 멈추고 현재 상태를 유지함
     *         TASK_YIELD: 비차단 대기 (다음 틱에서 해당 태스크부터 다시 시작)
     */
    virtual int Execute(ICXParam* xp, ICXContext* ctx) = 0;

    //-- 속성 관리
    void SetMaxRetries(int r) { m_maxRetries = r; }
    void SetTimeout(int s) { m_timeoutSeconds = s; }

    int  GetRetryCount() const { return m_retryCount; }
    void IncrementRetry() { m_retryCount++; }
    void ResetRetry() { m_retryCount = 0; m_startTime = 0; }

    bool IsTimedOut() {
        if(m_timeoutSeconds <= 0) return false;
        if(m_startTime == 0) m_startTime = TimeCurrent();
        bool timedOut = (TimeCurrent() - m_startTime >= m_timeoutSeconds);
        if(timedOut) ResetRetry(); // 타임아웃 발생 시 상태 초기화 (재시도 루프 종료용)
        return timedOut;
    }

    bool IsMaxRetriesExceeded() const {
        return (m_maxRetries > 0 && m_retryCount >= m_maxRetries);
    }
};

#endif

#ifndef CXSTEPENTRY_MQH
#define CXSTEPENTRY_MQH

#include "..\..\..\Interfaces\IXStep.mqh"
#include "..\..\..\Interfaces\CXDefine.mqh"
#include "..\..\..\Interfaces\CXMacros.mqh"
#include "..\..\..\Interfaces\IXOrderManager.mqh"
#include "..\..\..\Infra\CXMessageProvider.mqh"

/**
 * @class CXStepEntry
 * @brief 신규 주문 진입에 해당하는 원자적 단계 (IXStep 구현)
 */
class CXStepEntry : public IXStep {
private:
    string m_name;

public:
    CXStepEntry() : m_name("Step_Entry") {}
    virtual ~CXStepEntry() {}

    virtual string Name() override { return m_name; }

    /**
     * @brief 진입 조건 확인 (xa_entry == XA_ACTIVE AND xe_status < XE_EXECUTED)
     */
    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return false;

        // spec.md: Entry activation (xa_entry == XA_ACTIVE AND xe_status < XE_EXECUTED)
        // xa_status 제거에 따라 Intent(xa_entry) 존재 여부만으로 즉시 진입 시도
        return (sig.GetXAEntry() == XA_ACTIVE &&
                sig.GetStatus() < XE_EXECUTED);
    }
    /**
     * @brief 진입 로직 실행
     */
    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        XP_LOG_INFO(xp, "[STEP-ENTRY] Executing Market/Trailing Entry...");

        IXOrderManager* orderMgr = CX_GET_OBJ(ctx, "order_mgr", IXOrderManager);
        if(IS_VALID(orderMgr)) {
            if(orderMgr.ExecuteEntry(xp)) {
                ICXSignal* sig = xp.GetSignal();
                if(IS_VALID(sig) && sig.GetType() == ORDER_MARKET) {
                    return SESSION_ACTIVE;
                }
                return STATE_ENTRY_TRAILING;
            }
        }

        XP_LOG_ERROR(xp, "[STEP-ENTRY] Entry execution failed. Transitioning to SESSION_ERROR.");
        return SESSION_ERROR; // 실패 시 에러 상태로 전이하여 좀비 세션 방지
    }

    virtual void OnEnter(ICXContext* ctx) override {
        XP_LOG_DEBUG(NULL, "[STEP-ENTRY] Entering Entry State");
    }

    virtual void OnExit(ICXContext* ctx) override {
        XP_LOG_DEBUG(NULL, "[STEP-ENTRY] Exiting Entry State");
    }
};

#endif

#ifndef ENTRYTASKS_MQH
#define ENTRYTASKS_MQH

#include "..\..\Interfaces\IXTask.mqh"
#include "..\..\Interfaces\CXMacros.mqh"
#include "..\..\Interfaces\IXOrderManager.mqh"
#include "..\..\Interfaces\IXGuard.mqh"
#include "..\..\Interfaces\IRepository.mqh"
#include "..\..\Infra\CXMessageProvider.mqh"

/**
 * @class CXTaskEntry_L_Validate
 * @brief [Logic] 진입 조건 및 가드 검증 (I/O 없음)
 */
class CXTaskEntry_L_Validate : public IXTask {
public:
    virtual string Name() override { return "Entry_L_Validate"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IXGuard* guard = CX_GET_OBJ(ctx, "guard", IXGuard);
        if(IS_INVALID(sig)) return TASK_BREAK;

        // 1. 상태 및 의도 검증
        if(sig.GetStatus() == XE_ERROR) return SESSION_ERROR;
        if(sig.GetXAEntry() != XA_ACTIVE || sig.GetStatus() >= XE_EXECUTED) return TASK_BREAK;

        // 2. 가드 검증 (Margin, StopLevel 등)
        if(IS_VALID(guard)) {
            if(!guard.ValidateLot(sig.GetSymbol(), sig.GetLot())) {
                XP_LOG_WARN(xp, "[ENTRY-L] Lot/Margin Validation Failed.");
                return TASK_BREAK;
            }
        }

        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskEntry_P_Lock
 * @brief [Persistence] DB에 PENDING_REQ 상태 기록 (잠금)
 */
class CXTaskEntry_P_Lock : public IXTask {
public:
    virtual string Name() override { return "Entry_P_Lock"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IRepository* repo = CX_GET_OBJ(ctx, "repo", IRepository);
        if(IS_INVALID(sig) || IS_INVALID(repo)) return TASK_BREAK;

        // 이미 잠금 상태거나 그 이상이면 통과
        if(sig.GetStatus() >= XE_PENDING_REQ) return TASK_CONTINUE;

        CXMessageProvider::UpdateStatus(sig, XE_PENDING_REQ, "Intent: Entry Requesting...");
        if(repo.UpdateStatus(sig)) {
            return TASK_CONTINUE;
        }

        XP_LOG_ERROR(xp, "[ENTRY-P] Failed to Write PENDING_REQ Lock to DB.");
        return TASK_BREAK; 
    }
};

/**
 * @class CXTaskEntry_R_Order
 * @brief [Request] 브로커에 주문 송신
 */
class CXTaskEntry_R_Order : public IXTask {
public:
    virtual string Name() override { return "Entry_R_Order"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        IXOrderManager* orderMgr = CX_GET_OBJ(ctx, "order_mgr", IXOrderManager);
        if(IS_INVALID(orderMgr)) return TASK_BREAK;

        // 이미 티켓이 있거나 체결된 경우 (재진입 방지)
        ICXSignal* sig = xp.GetSignal();
        if(IS_VALID(sig) && (sig.GetTicket() > 0 || sig.GetStatus() >= XE_IN_TRANSIT)) return TASK_CONTINUE;

        XP_LOG_INFO(xp, "[ENTRY-R] Sending Order to Broker...");
        if(orderMgr.ExecuteEntry(xp)) {
            return TASK_CONTINUE;
        }

        XP_LOG_ERROR(xp, "[ENTRY-R] Broker Order Send Failed.");
        return SESSION_ERROR;
    }
};

/**
 * @class CXTaskEntry_V_Ticket
 * @brief [Verify] 티켓 번호 획득 및 과도기 상태 검증
 */
class CXTaskEntry_V_Ticket : public IXTask {
public:
    virtual string Name() override { return "Entry_V_Ticket"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return TASK_BREAK;

        // 티켓 번호 확인 (ExecuteEntry에서 채워졌어야 함)
        if(sig.GetTicket() <= 0) {
            if(IsTimedOut()) {
                XP_LOG_ERROR(xp, "[ENTRY-V] Ticket Acquisition Timeout.");
                return SESSION_ERROR;
            }
            return TASK_YIELD; // 다음 틱에서 재확인
        }

        // 실물 존재 확인 단계(V_Real)로 전이하기 위해 상태 업데이트
        CXMessageProvider::UpdateStatus(sig, XE_IN_TRANSIT, StringFormat("Ticket Obtained: %I64u. Verifying Asset...", sig.GetTicket()));
        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskEntry_V_Real
 * @brief [Verify] 터미널 내 실물 자산(Position/Order) 존재 확인
 */
class CXTaskEntry_V_Real : public IXTask {
public:
    virtual string Name() override { return "Entry_V_Real"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return TASK_BREAK;

        ulong ticket = (ulong)sig.GetTicket();
        bool exists = false;

        if(sig.GetType() == ORDER_MARKET) {
            exists = PositionSelectByTicket(ticket);
        } else {
            exists = OrderSelect(ticket);
        }

        if(!exists) {
            if(IsTimedOut()) {
                XP_LOG_ERROR(xp, StringFormat("[ENTRY-V] Real Asset(%I64u) Verification Timeout.", ticket));
                return SESSION_ERROR;
            }
            return TASK_YIELD; // 터미널 동기화 대기
        }

        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskEntry_P_Finalize
 * @brief [Persistence] DB 상태 최종 확정
 */
class CXTaskEntry_P_Finalize : public IXTask {
public:
    virtual string Name() override { return "Entry_P_Finalize"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IRepository* repo = CX_GET_OBJ(ctx, "repo", IRepository);
        if(IS_INVALID(sig) || IS_INVALID(repo)) return TASK_BREAK;

        int targetStatus = (sig.GetType() == ORDER_MARKET) ? XE_EXECUTED : XE_PENDING_PLACED;
        string msg = (targetStatus == XE_EXECUTED) ? "Entry Executed (Market)" : "Entry Pending Placed (Trailing)";

        CXMessageProvider::UpdateStatus(sig, targetStatus, msg);
        if(repo.UpdateStatus(sig)) {
            XP_LOG_OK(xp, StringFormat("[ENTRY-P] Finalized Status: %d", targetStatus));
            return (targetStatus == XE_EXECUTED) ? SESSION_ACTIVE : STATE_ENTRY_TRAILING;
        }

        return TASK_YIELD; // DB 지연 시 재시도
    }
};

#endif

#ifndef CXCOMPOSITESTEP_MQH
#define CXCOMPOSITESTEP_MQH

#include "..\..\Interfaces\IXStep.mqh"
#include "..\..\Interfaces\IXTask.mqh"
#include "..\..\Interfaces\CXMacros.mqh"
#include <Arrays\ArrayObj.mqh>

/**
 * @class CXCompositeStep
 * @brief 여러 개의 IXTask(마이크로 태스크)를 조립하여 순차 실행하는 복합 시퀀스 스텝
 */
class CXCompositeStep : public IXStep {
private:
    string      m_name;
    CArrayObj   m_tasks;
    int         m_currentTaskIndex; // [Refinement 1] Resume Pointer
    bool        m_hasConditionFunc;

public:
    CXCompositeStep(string name) : m_name(name), m_currentTaskIndex(0), m_hasConditionFunc(false) {}
    virtual ~CXCompositeStep() {
        m_tasks.Clear();
    }

    virtual string Name() override { return m_name; }

    /**
     * @brief 실행할 태스크를 체인에 추가합니다.
     */
    CXCompositeStep* AddTask(IXTask* task) {
        if(IS_VALID(task)) {
            m_tasks.Add(task);
        }
        return GetPointer(this);
    }

    /**
     * @brief 기본적으로 true를 반환하며, 태스크 내부 로직에서 조건을 필터링합니다.
     */
    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        return true; 
    }

    /**
     * @brief 등록된 태스크들을 순차적으로 실행
     */
    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        for(int i = m_currentTaskIndex; i < m_tasks.Total(); i++) {
            IXTask* task = dynamic_cast<IXTask*>(m_tasks.At(i));
            if(IS_VALID(task)) {
                // [v9.9.2] 타임아웃 검증
                if(task.IsTimedOut()) {
                    XP_LOG_ERROR(xp, StringFormat("[%s] Task Timeout. Moving to SESSION_ERROR.", task.Name()));
                    m_currentTaskIndex = 0; // Reset
                    return SESSION_ERROR;
                }

                int res = task.Execute(xp, ctx);

                // 1. 특정 상태로 전이 지시 시 즉시 반환 (성공/상태변경)
                if(res >= 0) {
                    task.ResetRetry(); 
                    m_currentTaskIndex = 0; // Reset for next state
                    return res;
                }
                // 2. 실행 중지(Break) 지시 시 남은 태스크 무시하고 현재 상태 유지
                else if(res == TASK_BREAK) {
                    m_currentTaskIndex = 0; // Restart chain on next process call
                    return STATE_UNCHANGED;
                }
                // 3. 비차단 대기(Yield) 시 인덱스 유지하고 다음 틱 대기
                else if(res == TASK_YIELD) {
                    m_currentTaskIndex = i; // [Refinement 1] Save current position
                    task.IncrementRetry();
                    if(task.IsMaxRetriesExceeded()) {
                        XP_LOG_ERROR(xp, StringFormat("[%s] Max Retries Exceeded. Moving to SESSION_ERROR.", task.Name()));
                        m_currentTaskIndex = 0;
                        return SESSION_ERROR;
                    }
                    return STATE_UNCHANGED;
                }
                // 4. TASK_CONTINUE(-1) 시 다음 태스크로 진행
                else if(res == TASK_CONTINUE) {
                    task.ResetRetry(); 
                    m_currentTaskIndex = i + 1; // Move to next
                }
            }
        }

        m_currentTaskIndex = 0; // 체인 완주 시 리셋
        return STATE_UNCHANGED; 
    }

    virtual void OnEnter(ICXContext* ctx) override {
        m_currentTaskIndex = 0; // 진입 시 항상 0부터 시작
        XP_LOG_DEBUG(NULL, StringFormat("[%s] Composite Step Entered (%d tasks)", m_name, m_tasks.Total()));
    }

    virtual void OnExit(ICXContext* ctx) override {
        m_currentTaskIndex = 0; 
        XP_LOG_DEBUG(NULL, StringFormat("[%s] Composite Step Exited", m_name));
    }
};

#endif

