/**
 * @class CXTaskPending_V_Sync
 * @brief [Verify] 터미널 실물 상태 동기화 및 외부 명령 감시
 */
class CXTaskPending_V_Sync : public IXTask {
public:
    virtual string Name() override { return "Pending_V_Sync"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return TASK_BREAK;

        // 1. 하드 에러 검증
        if(sig.GetStatus() == XE_ERROR) return SESSION_ERROR;

        // 2. 외부 청산 명령 검지
        if(sig.GetXAExit() == XA_ACTIVE) {
            XP_LOG_WARN(xp, "[PENDING-V] Exit command detected. Moving to LIQUIDATING.");
            return SESSION_LIQUIDATING;
        }

        // 3. 체결 여부 확인 (이전 단계에서 Executed 되었을 수 있음)
        if(sig.GetStatus() >= XE_EXECUTED) return SESSION_ACTIVE;

        // 4. 대기 오더 티켓 유효성 확인
        if(sig.GetTicket() <= 0) return TASK_BREAK;

        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskPending_L_Rebound
 * @brief [Logic] 반등 감지 (Market 전환 여부 판단)
 */
class CXTaskPending_L_Rebound : public IXTask {
public:
    virtual string Name() override { return "Pending_L_Rebound"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig) || sig.GetTEStart() <= 0) return TASK_CONTINUE;

        double point = SymbolInfoDouble(sig.GetSymbol(), SYMBOL_POINT);
        double currentPrice = SymbolInfoDouble(sig.GetSymbol(), (sig.GetDir() == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);

        // 반등 감지 (Market 전환 지시)
        bool is_rebounded = (sig.GetDir() == CX_DIR_BUY) ? (currentPrice > sig.GetPriceSignal() + (sig.GetTEStep() * 1 * point))
                                                         : (currentPrice < sig.GetPriceSignal() - (sig.GetTEStep() * 1 * point));
        if(is_rebounded) {
            xp.SetInt(10); // Rebound Flag
            return TASK_CONTINUE;
        }

        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskPending_L_Improve
 * @brief [Logic] 진입 트레일링 가격 개선 계산
 */
class CXTaskPending_L_Improve : public IXTask {
public:
    virtual string Name() override { return "Pending_L_Improve"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig) || sig.GetTEStart() <= 0 || xp.GetInt() == 10) return TASK_CONTINUE;

        IXPriceTracker* tracker = CX_GET_OBJ(ctx, "price_tracker", IXPriceTracker);
        if(IS_INVALID(tracker)) return TASK_BREAK;

        double point = SymbolInfoDouble(sig.GetSymbol(), SYMBOL_POINT);
        double currentPrice = SymbolInfoDouble(sig.GetSymbol(), (sig.GetDir() == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
        tracker.Update(currentPrice);

        double dir_sign = (sig.GetDir() == CX_DIR_BUY) ? -1.0 : 1.0;
        double target = currentPrice + (sig.GetTEStart() * point * dir_sign);

        bool is_improved = (sig.GetDir() == CX_DIR_BUY) ? (target < sig.GetPriceSignal() - sig.GetTEStep() * point) 
                                                        : (target > sig.GetPriceSignal() + sig.GetTEStep() * point);

        if(is_improved) {
            double newPrice = NormalizeDouble(target, (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));
            xp.SetDouble(newPrice);
            xp.SetInt(1); // Price Update Flag
        }

        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskPending_R_Apply
 * @brief [Request] 계산된 가격을 브로커에 적용 및 DB 기록
 */
class CXTaskPending_R_Apply : public IXTask {
public:
    virtual string Name() override { return "Pending_R_Apply"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IXOrderManager* orderMgr = CX_GET_OBJ(ctx, "order_mgr", IXOrderManager);
        IRepository* repo = CX_GET_OBJ(ctx, "repo", IRepository);
        if(IS_INVALID(sig) || IS_INVALID(orderMgr)) return TASK_BREAK;

        int flag = xp.GetInt(); 

        // --- 1. 반등 처리 (Market Fallback) ---
        if(flag == 10) {
            XP_LOG_WARN(xp, "[PENDING-R] Market Fallback due to Rebound.");
            if(orderMgr.DeleteOrder((ulong)sig.GetTicket())) {
                sig.SetType(ORDER_MARKET);
                if(orderMgr.ExecuteEntry(xp)) {
                    if(IS_VALID(repo)) repo.UpdateStatus(sig);
                    return SESSION_ACTIVE;
                }
            }
            return SESSION_ERROR;
        }

        // --- 2. 가격 갱신 처리 ---
        double newPrice = xp.GetDouble();
        if(newPrice > 0) {
            IXGuard* guard = CX_GET_OBJ(ctx, "guard", IXGuard);
            double currentPrice = SymbolInfoDouble(sig.GetSymbol(), (sig.GetDir() == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);

            if(IS_VALID(guard) && !guard.ValidateStopLevel(sig.GetSymbol(), currentPrice, newPrice)) return TASK_BREAK;

            if(orderMgr.ModifyOrder((ulong)sig.GetTicket(), newPrice, sig.GetSL(), sig.GetTP())) {
                sig.UpdatePriceSignal(newPrice);
                CXMessageProvider::UpdateStatus(sig, sig.GetStatus(), MSG_ENTRY_TRAILING_MODIFIED);
                if(IS_VALID(repo)) repo.UpdateStatus(sig);
                XP_LOG_INFO(xp, StringFormat("[PENDING-R] Order Modified. New Price:%.5f", newPrice));
            }
        }

        return TASK_CONTINUE;
    }
};

