/**
 * @class CXTaskExit_L_Prepare
 * @brief [Logic] 청산 조건 검증 및 준비 (I/O 없음)
 */
class CXTaskExit_L_Prepare : public IXTask {
public:
    virtual string Name() override { return "Exit_L_Prepare"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return TASK_BREAK;

        // 이미 청산 완료된 상태라면 종료
        if(sig.GetStatus() >= XE_CLOSED_SIGNAL) return SESSION_CLOSED;

        // 청산 의도 확인 (XA_EXIT == ACTIVE)
        if(sig.GetXAExit() != XA_ACTIVE) {
            // 강제 청산 시나리오가 아님에도 이 단계에 왔다면, SL/TP 히트 등 터미널 소멸 여부 재확인 필요
            return TASK_CONTINUE; 
        }

        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskExit_P_Lock
 * @brief [Persistence] DB에 청산 진행 중 상태 기록 (잠금)
 */
class CXTaskExit_P_Lock : public IXTask {
public:
    virtual string Name() override { return "Exit_P_Lock"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IRepository* repo = CX_GET_OBJ(ctx, "repo", IRepository);
        if(IS_INVALID(sig) || IS_INVALID(repo)) return TASK_BREAK;

        // 이미 잠금 상태거나 그 이상이면 통과
        if(sig.GetStatus() >= XE_PENDING_REQ) return TASK_CONTINUE;

        CXMessageProvider::UpdateStatus(sig, sig.GetStatus(), "Intent: Liquidation Requesting...");
        if(repo.UpdateStatus(sig)) {
            return TASK_CONTINUE;
        }

        return TASK_YIELD; 
    }
};

/**
 * @class CXTaskExit_R_Order
 * @brief [Request] 브로커에 청산(Close/Cancel) 주문 송신
 */
class CXTaskExit_R_Order : public IXTask {
public:
    virtual string Name() override { return "Exit_R_Order"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        IXExitManager* exitMgr = CX_GET_OBJ(ctx, "exit_mgr", IXExitManager);
        if(IS_INVALID(exitMgr)) return TASK_BREAK;

        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return TASK_BREAK;

        // 이미 청산 처리 중(In-Transit)이면 대기
        if(xp.GetInt() == 3) return TASK_CONTINUE;

        XP_LOG_INFO(xp, "[EXIT-R] Sending Liquidation Order to Broker...");
        if(exitMgr.CloseByTicket(sig)) {
            xp.SetInt(3); // In-Transit Mark
            return TASK_CONTINUE;
        }

        XP_LOG_ERROR(xp, "[EXIT-R] Broker Liquidation Request Failed.");
        return SESSION_ERROR;
    }
};

/**
 * @class CXTaskExit_V_Terminal
 * @brief [Verify] 터미널 내 실물 자산 소멸 확인 (L3 Verification)
 */
class CXTaskExit_V_Terminal : public IXTask {
public:
    virtual string Name() override { return "Exit_V_Terminal"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return TASK_BREAK;

        ulong ticket = (ulong)sig.GetTicket();
        if(ticket <= 0) return TASK_CONTINUE; // 티켓이 없으면 이미 소멸로 간주

        bool exists = false;
        if(sig.GetType() == ORDER_MARKET) {
            exists = PositionSelectByTicket(ticket);
        } else {
            exists = OrderSelect(ticket);
        }

        if(exists) {
            IncrementRetry();
            if(GetRetryCount() > 5) { // 5회 이상 존재하면 청산 실패로 간주
                XP_LOG_ERROR(xp, StringFormat("[EXIT-V] Physical Asset(%I64u) still exists after 5 retries.", ticket));
                return SESSION_ERROR;
            }
            return TASK_YIELD; // 터미널 동기화 대기
        }

        XP_LOG_OK(xp, StringFormat("[EXIT-V] Physical Asset(%I64u) Absence Verified.", ticket));
        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskExit_P_Finalize
 * @brief [Persistence] DB 상태 최종 확정 (CLOSED)
 */
class CXTaskExit_P_Finalize : public IXTask {
public:
    virtual string Name() override { return "Exit_P_Finalize"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IRepository* repo = CX_GET_OBJ(ctx, "repo", IRepository);
        if(IS_INVALID(sig) || IS_INVALID(repo)) return TASK_BREAK;

        // 청산 사유에 따른 최종 상태 코드 결정
        int finalStatus = sig.GetStatus();
        if(finalStatus < XE_CLOSED_SIGNAL) finalStatus = XE_CLOSED_SIGNAL;

        CXMessageProvider::UpdateStatus(sig, finalStatus, "Liquidation Finalized. Session Closed.");
        if(repo.UpdateStatus(sig)) {
            XP_LOG_OK(xp, StringFormat("[EXIT-P] Finalized Status: %d", finalStatus));
            return SESSION_CLOSED;
        }

        return TASK_YIELD; 
    }
};

