/**
 * @class CXTaskActive_V_Terminal
 * @brief [Verify] 터미널 실물 상태 확인 (SL/TP 히트 여부 등)
 */
class CXTaskActive_V_Terminal : public IXTask {
public:
    virtual string Name() override { return "Active_V_Terminal"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return TASK_BREAK;

        ulong ticket = (ulong)sig.GetTicket();
        bool exists = PositionSelectByTicket(ticket);

        // 자산이 사라졌다면(SL/TP 히트 또는 수동 청산) 다음 단계(Align)에서 DB 동기화 필요
        xp.SetInt(exists ? 1 : 0); 
        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskActive_P_Align
 * @brief [Persistence] 터미널 상태와 DB 상태 동기화
 */
class CXTaskActive_P_Align : public IXTask {
public:
    virtual string Name() override { return "Active_P_Align"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        IRepository* repo = CX_GET_OBJ(ctx, "repo", IRepository);
        if(IS_INVALID(sig) || IS_INVALID(repo)) return TASK_BREAK;

        bool exists = (xp.GetInt() == 1);

        // 터미널엔 없는데 DB가 아직 EXECUTED 상태면 외부 청산으로 간주하고 업데이트
        if(!exists && sig.GetStatus() < XE_CLOSED_SIGNAL) {
            IXPositionManager* posMgr = CX_GET_OBJ(ctx, "pos_mgr", IXPositionManager);
            if(IS_VALID(posMgr)) {
                posMgr.Pulse(xp); // 상세 청산 사유(TP/SL 등) 파악
            }
            repo.UpdateStatus(sig);
            XP_LOG_INFO(xp, "[ACTIVE-P] Terminal state mismatch detected. DB Aligned.");
        }

        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskActive_L_Status
 * @brief [Logic] 현재 상태에 따른 시퀀스 전이 판단
 */
class CXTaskActive_L_Status : public IXTask {
public:
    virtual string Name() override { return "Active_L_Status"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return TASK_BREAK;

        if(sig.GetStatus() >= XE_CLOSED_SIGNAL) {
            return SESSION_LIQUIDATING;
        }

        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskIntentWatch
 * @brief 외부 강제 청산 의도 모니터링
 */
class CXTaskIntentWatch : public IXTask {
public:
    virtual string Name() override { return "Task_IntentWatch"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig) || sig.GetStatus() == XE_ERROR) return TASK_BREAK;

        if(sig.GetXAExit() == XA_ACTIVE) {
            CXMessageProvider::UpdateStatus(sig, sig.GetStatus(), MSG_EXIT_REQUESTED);
            XP_LOG_INFO(xp, "[TASK-INTENT] Exit Command (XA_ACTIVE) Detected. Moving to LIQUIDATING.");
            return SESSION_LIQUIDATING;
        }

        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskAlphaCalc
 * @brief 알파(익절 트레일링) 로직 계산 (Pure Logic)
 */
class CXTaskAlphaCalc : public IXTask {
public:
    virtual string Name() override { return "Task_AlphaCalc"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig) || sig.GetStatus() == XE_ERROR) return TASK_BREAK;

        // 트레일링 미사용 시 즉시 종료
        if(sig.GetTSStart() <= 0) return TASK_BREAK;

        IXPriceTracker* tracker = CX_GET_OBJ(ctx, "price_tracker", IXPriceTracker);
        if(IS_INVALID(tracker)) return TASK_BREAK;

        double point = SymbolInfoDouble(sig.GetSymbol(), SYMBOL_POINT);
        double currentPrice = SymbolInfoDouble(sig.GetSymbol(), (sig.GetDir() == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
        tracker.Update(currentPrice);

        double dir_sign = (sig.GetDir() == CX_DIR_BUY) ? 1.0 : -1.0;
        double profit = (currentPrice - sig.GetPriceOpen()) * dir_sign;

        if(profit >= sig.GetTSStart() * point) {
            double peak = (sig.GetDir() == CX_DIR_BUY) ? tracker.GetHighest() : tracker.GetLowest();
            double target = peak - (sig.GetTSStart() * point * dir_sign);

            bool is_improved = (sig.GetDir() == CX_DIR_BUY) ? (target > sig.GetSL() + sig.GetTSStep() * point)
                                                            : (target < sig.GetSL() - sig.GetTSStep() * point || sig.GetSL() == 0);

            if(is_improved) {
                double newSL = NormalizeDouble(target, (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));
                xp.SetDouble(newSL);
                return TASK_CONTINUE;
            }
        }

        xp.SetDouble(0); // 변화 없음
        return TASK_CONTINUE;
    }
};

/**
 * @class CXTaskAlphaApply
 * @brief 계산된 SL/TP를 브로커에 적용 (Action)
 */
class CXTaskAlphaApply : public IXTask {
public:
    virtual string Name() override { return "Task_AlphaApply"; }
    virtual int Execute(ICXParam* xp, ICXContext* ctx) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig) || sig.GetStatus() == XE_ERROR) return TASK_BREAK;

        double newSL = xp.GetDouble();
        if(newSL <= 0) return TASK_CONTINUE;

        IXPositionManager* posMgr = CX_GET_OBJ(ctx, "pos_mgr", IXPositionManager);
        IXGuard* guard = CX_GET_OBJ(ctx, "guard", IXGuard);
        if(IS_INVALID(posMgr)) return TASK_BREAK;

        double currentPrice = SymbolInfoDouble(sig.GetSymbol(), (sig.GetDir() == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);

        if(IS_VALID(guard) && !guard.ValidateStopLevel(sig.GetSymbol(), currentPrice, newSL)) {
            return TASK_BREAK;
        }

        if(posMgr.ModifyPosition((ulong)sig.GetTicket(), newSL, sig.GetTP())) {
            sig.SetSL(newSL);
            sig.SetStatusMsg(MSG_EXIT_TS_MODIFIED);
            XP_LOG_INFO(xp, StringFormat("[TASK-TS] SL Updated: %.5f", newSL));
        }

        return TASK_CONTINUE;
    }
};

