        // --- SID Decomposition & Composition ---
        private string _yymmddhh = string.Empty;
        public string yymmddhh 
        { 
            get => _yymmddhh; 
            set { if (_yymmddhh != value) { _yymmddhh = value; UpdateSid(); RaisePropertyChanged(nameof(yymmddhh)); } } 
        }

