 */
virtual bool ModifyPosition(ulong ticket, double sl, double tp) override {
    XP_LOG_TRACE(NULL, StringFormat("[POS-MODIFY] Sending Request: [Ticket:%I64u, SL:%.5f, TP:%.5f]", 
                                    ticket, sl, tp));

    // 1. 수정 시도
    if(!m_trade.PositionModify(ticket, sl, tp)) {
        string retMsg = m_trade.ResultRetcodeDescription();
        uint retCode = m_trade.ResultRetcode();
        int sysErr = GetLastError();
        XP_LOG_ERROR(NULL, StringFormat("[POS-MODIFY] FAILED: %s (BrokerCode:%u, SystemErr:%d). Req:[Ticket:%I64u, SL:%.5f, TP:%.5f]", 
                                        retMsg, retCode, sysErr, ticket, sl, tp));
        ResetLastError();
        return false;
    }

    // 2. 재확인
    if(PositionSelectByTicket(ticket)) {
        double currentSL = PositionGetDouble(POSITION_SL);
        double currentTP = PositionGetDouble(POSITION_TP);

        if(MathAbs(currentSL - sl) < _Point * 10 && MathAbs(currentTP - tp) < _Point * 10) {
            XP_LOG_OK(NULL, StringFormat("[POS-MODIFY] SUCCESS: Ticket %I64u Modified.", ticket));
            return true;
        }
    }

    XP_LOG_ERROR(NULL, StringFormat("[POS-MODIFY] VERIFY FAILED: Modification sent but values not reflected for ticket:%I64u", ticket));
    return false;
}

