/**
 * @class CXStepBinding
 * @brief 검증된 신호를 SessionPool에서 세션에 할당하고 기동하는 단계
 */
class CXStepBinding : public IXStep {
public:
    CXStepBinding() {}
    virtual ~CXStepBinding() {}

    virtual string Name() override { return "Step_Binding"; }

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        CArrayObj* activeList = CX_GET_OBJ(ctx, "active_signals", CArrayObj);
        return (IS_VALID(activeList) && activeList.Total() > 0);
    }

    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        CArrayObj* activeList = CX_GET_OBJ(ctx, "active_signals", CArrayObj);
        ICXTradingSessionPool* pool = CX_GET_OBJ(ctx, "session_pool", ICXTradingSessionPool);
        ICXLogger* log = CX_GET_OBJ(ctx, "logger", ICXLogger);

        if(IS_INVALID(activeList) || IS_INVALID(pool)) return WATCHER_DISCOVERY;

        int total = activeList.Total();
        int success = 0;
        int skipped = 0;
        int failed = 0;

        for(int i = 0; i < total; i++) {
            ICXSignal* sig = CX_CAST(ICXSignal, activeList.At(i));
            if(IS_INVALID(sig)) continue;

            string sid = sig.GetSid();

            //-- 0. 중복 바인딩 방지
            ICXTradingSession* existing = pool.FindSessionBySid(sid);
            if(IS_VALID(existing)) {
                if(IS_VALID(log)) log.Debug(xp, StringFormat("[WATCHER-BINDING] SKIP: SID:%s is already active.", sid));
                skipped++;
                SAFE_DELETE(sig); //-- [v10.7 Fix] Delete orphan signal object
                continue;
            }

            //-- 1. 세션 풀에서 세션 대여
            ICXTradingSession* session = pool.BorrowSession();
            if(IS_VALID(session)) {
                //-- 2. 세션 기동 및 신호 주입 (Ownership transfer to Session)
                CXParam sp;
                sp.SetSignal(sig);
                session.Start(GetPointer(sp));

                if(IS_VALID(log)) log.Ok(xp, StringFormat("[WATCHER-BINDING] SUCCESS: SID:%s bound to session.", sid));
                success++;
            } else {
                if(IS_VALID(log)) log.Error(xp, StringFormat("[WATCHER-BINDING] FAILED: No idle session for SID:%s", sid));
                failed++;
                SAFE_DELETE(sig); //-- [v10.7 Fix] Delete orphan signal object
            }
        }

        if(total > 0) {
            if(IS_VALID(log)) log.Info(xp, StringFormat("[WATCHER-BINDING] Complete. Success: %d, Skipped: %d, Failed: %d", success, skipped, failed));
        }

        // 3. 작업 완료 후 리스트 정리
        while(activeList.Total() > 0) activeList.Detach(0); 

        return WATCHER_DISCOVERY;
    }

    virtual void OnEnter(ICXContext* ctx) override {}
    virtual void OnExit(ICXContext* ctx) override {}
};

#endif

#ifndef CXTRADINGSESSIONPOOL_MQH
#define CXTRADINGSESSIONPOOL_MQH

#include <Arrays\ArrayObj.mqh>
#include "..\Session\CXTradingSession.mqh"
#include "..\Interfaces\ICXTradingSessionPool.mqh"

/**
 * @class CXTradingSessionPool
 * @brief Sandboxed 세션들을 미리 생성하고 관리하는 풀 클래스
 */
class CXTradingSessionPool : public ICXTradingSessionPool {
private:
    CArrayObj     m_pool;      // 사용 가능한 유휴 세션 풀
    CArrayObj     m_active;    // 현재 사용 중인 세션 리스트
    int           m_initialCount;

public:
    CXTradingSessionPool(int count) : m_initialCount(count) {}
    virtual ~CXTradingSessionPool() {
        m_pool.Clear();
        m_active.Clear();
    }

    /**
     * @brief EA 초기화 시 지정된 개수만큼 샌드박스 세션 미리 생성 (Warm-up)
     */
    virtual void Initialize(IRepository* globalRepo, ICXContext* globalContext, ICXServiceFactory* factory) override {
        for(int i = 0; i < m_initialCount; i++) {
            // 각 세션은 고유의 자원(DB, Log 등)을 가질 수 있도록 리포지토리와 팩토리를 통해 생성
            CXTradingSession* session = new CXTradingSession(globalRepo, globalContext, factory);
            if(IS_VALID(session)) {
                m_pool.Add(session);
            }
        }
    }

    /**
     * @brief 풀에서 유휴 세션 획득 (Borrow)
     */
    virtual ICXTradingSession* BorrowSession() override {
        if(m_pool.Total() <= 0) return NULL; // 또는 추가 생성 로직

        ICXTradingSession* session = CX_CAST(ICXTradingSession, m_pool.Detach(0));
        m_active.Add(session);
        return session;
    }

    /**
     * @brief SID로 활성 세션 검색
     */
    virtual ICXTradingSession* FindSessionBySid(const string sid) override {
        if(sid == "") return NULL;
        for(int i = 0; i < m_active.Total(); i++) {
            ICXTradingSession* session = CX_CAST(ICXTradingSession, m_active.At(i));
            if(IS_VALID(session) && session.GetSid() == sid) return session;
        }
        return NULL;
    }

    /**
     * @brief 사용이 끝난 세션을 풀로 반환 (Return)
     */
    virtual void ReturnSession(ICXTradingSession* session) override {
        for(int i = 0; i < m_active.Total(); i++) {
            if(m_active.At(i) == session) {
                m_active.Detach(i);
                session.Reset(); // 상태 초기화 후 반환
                m_pool.Add(session);
                break;
            }
        }
    }

    /**
     * @brief 활성 세션들에 대해 주기적 로직(Pulse) 실행
     */
    virtual void Pulse(ICXParam* xp) override {
        for(int i = 0; i < m_active.Total(); i++) {
            ICXTradingSession* session = CX_CAST(ICXTradingSession, m_active.At(i));
            if(IS_VALID(session)) session.Pulse(xp);
        }
        PurgeClosed();
    }

    /**
     * @brief 종료된 세션을 감지하여 풀로 반환
     */
    void PurgeClosed() {
        for(int i = m_active.Total() - 1; i >= 0; i--) {
            ICXTradingSession* session = CX_CAST(ICXTradingSession, m_active.At(i));
            if(IS_VALID(session) && !session.IsActive()) {
                ReturnSession(session);
            }
        }
    }
};

#endif

