            xp.SetSignal(m_signal);
            sig = m_signal;
        }

        // 2.1 [v10.7 Fix] Transaction Filtering (Anti Cross-talk)
        if(xp.GetEvent() == EVENT_TRANSACTION) {
            CXParam* px = dynamic_cast<CXParam*>(xp);
