            }
        }

        // 3. 시퀀스 엔진 구동
        if(IS_VALID(m_sequence)) {
            m_sequence.Pulse(xp);

            // [v7.9 Error Recovery] 회로 차단기 등 치명적 에러 발생 시 처리
            if(m_sequence.State() == SESSION_ERROR) {
