        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return TASK_BREAK;

        XP_LOG_TRACE(xp, StringFormat("[EXIT-L-PREPARE] Checking Liquidation Intent for SID:%s (Status:%d, XAExit:%d)", 
