#ifndef CXSTEPMONITOR_MQH
#define CXSTEPMONITOR_MQH

#include "..\..\Interfaces\IXStep.mqh"
#include "..\..\Interfaces\CXDefine.mqh"
#include "..\..\Interfaces\CXMacros.mqh"
