        if(m_name != "SessionSeq") return true;

        // 1. Terminal State Protection (Session Based)
        if(from == SESSION_CLOSED || from == SESSION_ERROR) return false;

        // 2. Linear Flow Enforcement (Session Based)
        if(from == SESSION_READY) {
            //-- [v10.30] 허용 경로에 SESSION_LIQUIDATING 추가 (에러 상태에서의 즉각 청산 바이패스 지원)
            return (to == STATE_ENTRY_TRAILING || to == SESSION_ACTIVE || to == SESSION_LIQUIDATING || to == 3 || to == 4);
        }
        if(from == STATE_ENTRY_TRAILING) {
            return (to == SESSION_ACTIVE || to == SESSION_LIQUIDATING);
        }
        if(from == SESSION_ACTIVE) {
            return (to == SESSION_LIQUIDATING || to == STATE_EXIT_TRAILING || to == 12 || to == 15);
        }
        if(from == SESSION_LIQUIDATING) {
            return (to == STATE_EXIT_SWEEP || to == STATE_EXIT_VERIFY || to == SESSION_CLOSED || to == 21 || to == 22 || to == 23);
        }

        return true; 
    }

    void TriggerOnEnter(int state) {
        CXStepNode* node = NULL;
        if(m_map.TryGetValue(state, node) && IS_VALID(node)) node.step.OnEnter(m_ctx);
    }

    void TriggerOnExit(int state) {
        CXStepNode* node = NULL;
        if(m_map.TryGetValue(state, node) && IS_VALID(node)) node.step.OnExit(m_ctx);
    }
};

