#include "..\CXCompositeStep.mqh"
#include "..\..\Tasks\PendingTasks.mqh"

/**
 * @class CXStepEntryTrailing
 * @brief [v9.9.2] 지정가 주문의 실시간 가격 추적 및 수정 (Pending Pipeline)
 */
class CXStepEntryTrailing : public CXCompositeStep {
public:
    CXStepEntryTrailing() : CXCompositeStep("Step_EntryTrailing") {
        this.AddTask(new CXTaskPending_V_Sync())
            .AddTask(new CXTaskPending_L_Rebound())
            .AddTask(new CXTaskPending_L_Improve())
            .AddTask(new CXTaskPending_R_Apply());
    }

    virtual ~CXStepEntryTrailing() {}

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        // 주문이 배치된 상태(PENDING_PLACED)이면 트레일링 설정 유무와 무관하게 진입하여 감시
        return (IS_VALID(sig) && sig.GetStatus() == XE_PENDING_PLACED);
    }
};

#endif

