        if(finalSL <= 0 && sig.GetSL() > 0) {
            finalSL = NormalizeDouble(basePrice - (sig.GetSL() * point * dir_sign), (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));
            XP_LOG_TRACE(xp, StringFormat("[v10.32-CALC] SL Cal: Base:%.5f - (Offset:%.0f * Pt:%.5f) = %.5f", basePrice, sig.GetSL(), point, finalSL));
        }
        if(finalTP <= 0 && sig.GetTP() > 0) {
            finalTP = NormalizeDouble(basePrice + (sig.GetTP() * point * dir_sign), (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));
            XP_LOG_TRACE(xp, StringFormat("[v10.32-CALC] TP Cal: Base:%.5f + (Offset:%.0f * Pt:%.5f) = %.5f", basePrice, sig.GetTP(), point, finalTP));
