/**
 * @class CXStepEntry
 * @brief [v9.9.2] 신규 주문 진입 복합 단계 (L-P-R-V-V-P 파이프라인)
 */
class CXStepEntry : public CXCompositeStep {
public:
    CXStepEntry() : CXCompositeStep("Step_Entry") {
        // Hyper-Atomized 태스크 조립
        this.AddTask(new CXTaskEntry_L_Validate())
            .AddTask(new CXTaskEntry_P_Lock())
            .AddTask(new CXTaskEntry_R_Order())
            .AddTask(new CXTaskEntry_V_Ticket())
            .AddTask(new CXTaskEntry_V_Real())
            .AddTask(new CXTaskEntry_P_Finalize());
    }

    virtual ~CXStepEntry() {}

    /**
     * @brief 진입 조건 확인 (xa_entry == XA_ACTIVE AND xe_status < XE_EXECUTED)
     */
    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return false;

        // Intent(xa_entry) 활성화 및 실행 전 상태 확인
        return (sig.GetXAEntry() == XA_ACTIVE &&
                sig.GetStatus() < XE_EXECUTED);
    }
};

