        double basePrice = (sig.GetType() == ORDER_MARKET) ? marketPrice : execPrice;
        double finalSL = sig.GetPriceSL();
        double finalTP = sig.GetPriceTP();
        double point = SymbolInfoDouble(sig.GetSymbol(), SYMBOL_POINT);
        double dir_sign = (sig.GetDir() == CX_DIR_BUY) ? 1.0 : -1.0;

        if(finalSL <= 0 && sig.GetSL() > 0) {
            finalSL = NormalizeDouble(basePrice - (sig.GetSL() * point * dir_sign), (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));
            XP_LOG_TRACE(xp, StringFormat("[v10.32-CALC] SL Cal: Base:%.5f - (Offset:%.0f * Pt:%.5f) = %.5f", basePrice, sig.GetSL(), point, finalSL));
        }
        if(finalTP <= 0 && sig.GetTP() > 0) {
            finalTP = NormalizeDouble(basePrice + (sig.GetTP() * point * dir_sign), (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));
            XP_LOG_TRACE(xp, StringFormat("[v10.32-CALC] TP Cal: Base:%.5f + (Offset:%.0f * Pt:%.5f) = %.5f", basePrice, sig.GetTP(), point, finalTP));
        }

        //--- [v10.10 Enhancement] Pre-flight StopLevel Validation
        if(IS_VALID(guard)) {
            if(!guard.ValidateStopLevel(sig.GetSymbol(), marketPrice, finalSL) || !guard.ValidateStopLevel(sig.GetSymbol(), marketPrice, finalTP)) {
                string err = StringFormat("[EXEC-ENTRY] INVALID STOPS (Market-Based). Req:[Mkt:%.5f, SL:%.5f, TP:%.5f], Sym:%s", 
                                          marketPrice, finalSL, finalTP, sig.GetSymbol());
                XP_LOG_ERROR(xp, err);
                CXMessageProvider::UpdateStatus(sig, XE_ERROR, err);
                return false;
            }
        }

        //-- [v10.26] Calculate Distance from Market for Logging
        double distPoints = 0;
        if(point > 0) distPoints = MathAbs(marketPrice - execPrice) / point;

        //-- [v10.31] Comprehensive Execution Logging (Standard v10.4)
        double teLimitPts = sig.GetTELimit();
        double teLimitPrice = NormalizeDouble(marketPrice - (teLimitPts * point * dir_sign), (int)SymbolInfoInteger(sig.GetSymbol(), SYMBOL_DIGITS));

        string entryLog = StringFormat("[EXEC-ENTRY] Sending Order: [Sym:%s, Type:%s, Lot:%.2f, Price:%.5f, SL:%.5f, TP:%.5f, Mkt:%.5f, TELimPts:%.0f, TELimP:%.5f, TESta:%.0f, TESte:%.0f, SID:%s]", 
