                XP_LOG_SEQ_DEBUG(xp, StringFormat("[SEQ:%s] Transition: %d -> %d (Step: %s)", m_name, m_current_state, next_state, node.step.Name()));
                node.current_retries = 0; // 성공 전이 시 리셋
                UpdateState(next_state);
