        }

        TriggerOnExit(m_current_state);
        m_current_state = next;
        m_state_entered = TimeCurrent();
        TriggerOnEnter(m_current_state);
    }

    /**
     * @brief 상태 전이 정합성 검증 (Anti-Backtracking)
     */
    bool ValidateTransition(int from, int to) {
        if(to == SESSION_ERROR || to == 99) return true; // Error is always reachable
        if(from == -1) return true;                      // Init

        //-- [v10.22 Refinement] Fail-safe for Infrastructure Sequences
        //-- "SessionSeq"가 아닌 모든 시퀀스(WatcherSeq 등)는 제약 없이 전이 허용
