            return (to == SESSION_ACTIVE || to == SESSION_LIQUIDATING);
        }
        if(from == SESSION_ACTIVE) {
            return (to == SESSION_LIQUIDATING || to == STATE_EXIT_TRAILING || to == 12 || to == 15);
        }
