            return (to == STATE_EXIT_SWEEP || to == STATE_EXIT_VERIFY || to == SESSION_CLOSED || to == 21 || to == 22 || to == 23);
        }

        return true; 
    }

    void TriggerOnEnter(int state) {
        CXStepNode* node = NULL;
