        if(IS_VALID(m_ctx)) config = dynamic_cast<ICXConfig*>(m_ctx.Get("config"));

        m_logger = dynamic_cast<CXLogDispatcher*>(factory.CreateLogger(sid, config));
        if(IS_VALID(m_logger)) {
            m_ctx.Register("logger", m_logger);
        }
    }

