            uint retCode = m_trade.ResultRetcode();
            int sysErr = GetLastError();
            string typeStr = EnumToString(order_type);
            string err_msg = StringFormat("[EXEC-ENTRY-FAIL] Broker Code:%u(%s), SysErr:%d. Original Params: [Sym:%s, Type:%s, Lot:%.2f, P:%.5f, SL:%.5f, TP:%.5f, SID:%s]", 
                                          (uint)retCode, retMsg, (int)sysErr, sig.GetSymbol(), typeStr, (double)sig.GetLot(), (double)(sig.GetType() == ORDER_MARKET ? marketPrice : execPrice), (double)finalSL, (double)finalTP, m_sid);

