    virtual bool DeleteOrder(ICXParam* xp, ulong ticket) override {
        if(ticket == 0) return false;

        XP_LOG_INFO(xp, StringFormat("[ORDER-DELETE] Sending Request: [Ticket:%I64u]", ticket));

        // 1. 삭제 시도
        if(!m_trade.OrderDelete(ticket)) {
