        if(from == SESSION_READY) {
            //-- [v10.30] 허용 경로에 SESSION_LIQUIDATING 추가 (에러 상태에서의 즉각 청산 바이패스 지원)
            return (to == STATE_ENTRY_TRAILING || to == SESSION_ACTIVE || to == SESSION_LIQUIDATING || to == 3 || to == 4);
        }
