        // 로그 출력을 위한 임시 파라미터 (Context 연결 필수)
        CXParam xp;
        xp.SetContext(m_ctx);

        XP_LOG_TRACE(GetPointer(xp), "Assembling Sequence Architecture...");

        //-- 1. 진입 파이프라인 (Entry Pipeline) - Hyper-Atomized (L -> G -> G -> P -> R -> V -> V -> V -> V -> P)
        CXCompositeStep* entryStep = new CXCompositeStep("Step_EntryComposite");
        entryStep.AddTask(new CXTaskEntry_L_Validate())
                 .AddTask(new CXTaskGuard_V_Spread())
                 .AddTask(new CXTaskGuard_V_Volatility())
                 .AddTask(new CXTaskEntry_P_Lock())
                 .AddTask(new CXTaskEntry_R_Order())
                 .AddTask(new CXTaskEntry_V_Error())
                 .AddTask(new CXTaskEntry_V_Ticket())
                 .AddTask(new CXTaskEntry_V_Real())
                 .AddTask(new CXTaskFinalize_V_DoubleCheck())
                 .AddTask(new CXTaskEntry_P_Finalize());
        XP_LOG_TRACE(GetPointer(xp), " -> Added: Entry Pipeline (L-G-G-P-R-V-V-V-V-P)");

        seq.From(SESSION_READY).Execute(entryStep)
           .OnSuccess(STATE_ENTRY_TRAILING)
           .OnFail(SESSION_ERROR)
           .Case(SESSION_ACTIVE, SESSION_ACTIVE)
           .Case(SESSION_LIQUIDATING, SESSION_LIQUIDATING)
           .Timeout(300);

        //-- 2. 대기 파이프라인 (Pending Pipeline)
        CXCompositeStep* pendingStep = new CXCompositeStep("Step_PendingComposite");
        pendingStep.AddTask(new CXTaskPending_V_Sync())
                   .AddTask(new CXTaskPending_L_Rebound())
                   .AddTask(new CXTaskPending_L_Improve())
                   .AddTask(new CXTaskPending_R_Apply());
        XP_LOG_TRACE(GetPointer(xp), " -> Added: Pending Pipeline (V -> L -> L -> R)");

        seq.From(STATE_ENTRY_TRAILING).Execute(pendingStep)
           .OnSuccess(SESSION_ACTIVE)
           .OnFail(SESSION_ERROR)
           .Case(SESSION_LIQUIDATING, SESSION_LIQUIDATING)
           .Timeout(3600);

        //-- 3. 활성 파이프라인 (Monitoring & TS) (V -> V -> V -> P -> L -> Intent -> Calc -> Apply)
        CXCompositeStep* activeStep = new CXCompositeStep("Step_ActiveComposite");
        activeStep.AddTask(new CXTaskComm_V_Status())
                  .AddTask(new CXTaskSync_V_Stale())
                  .AddTask(new CXTaskActive_V_Terminal())
                  .AddTask(new CXTaskActive_P_Align())
                  .AddTask(new CXTaskActive_L_Status())
                  .AddTask(new CXTaskIntentWatch())
                  .AddTask(new CXTaskAlphaCalc())
                  .AddTask(new CXTaskAlphaApply());
        XP_LOG_TRACE(GetPointer(xp), " -> Added: Active Pipeline (V-V-V-P-L-I-C-A)");

        seq.From(SESSION_ACTIVE).Execute(activeStep)
           .Case(SESSION_LIQUIDATING, SESSION_LIQUIDATING)
           .Timeout(72000); 

        //-- 4. 청산 파이프라인 (Liquidation Pipeline) (L -> P -> R -> V -> V -> P)
        CXCompositeStep* exitStep = new CXCompositeStep("Step_ExitComposite");
        exitStep.AddTask(new CXTaskExit_L_Prepare())
                .AddTask(new CXTaskExit_P_Lock())
                .AddTask(new CXTaskExit_R_Order())
                .AddTask(new CXTaskExit_V_Error())
                .AddTask(new CXTaskExit_V_Terminal())
                .AddTask(new CXTaskExit_P_Finalize());
        XP_LOG_TRACE(GetPointer(xp), " -> Added: Liquidation Pipeline (L -> P -> R -> V -> V -> P)");

        seq.From(SESSION_LIQUIDATING).Execute(exitStep)
           .OnSuccess(SESSION_CLOSED)
           .OnFail(SESSION_ERROR)
           .Timeout(300)
