        IXPriceTracker* tracker = CX_GET_OBJ(ctx, "price_tracker", IXPriceTracker);

        if(IS_INVALID(sig) || IS_INVALID(orderMgr) || IS_INVALID(tracker)) return STATE_UNCHANGED;

