        // 보수적으로 청산 신호로 간주하여 시퀀스를 넘김
        CXMessageProvider::UpdateStatus(sig, XE_CLOSED_SIGNAL, "Position Not Found in Terminal");
        XP_LOG_WARN(xp, "[POS-MANAGER] Position missing but not in history. Force closing.");
    }

    /**
     * @brief 티켓으로 포지션 선택
     */
    bool SelectPosition(ICXParam* xp) {
        return false;
    }

    /**
     * @brief 브로커 포지션 수정 (SL/TP) 및 상태 재확인
     */
    virtual bool ModifyPosition(ulong ticket, double sl, double tp) override {
        XP_LOG_INFO(NULL, StringFormat("[POS-MODIFY] Sending Request: [Ticket:%I64u, SL:%.5f, TP:%.5f]", 
                                        ticket, sl, tp));

        // 1. 수정 시도
        if(!m_trade.PositionModify(ticket, sl, tp)) {
            string retMsg = m_trade.ResultRetcodeDescription();
            uint retCode = m_trade.ResultRetcode();
            int sysErr = GetLastError();
            XP_LOG_ERROR(NULL, StringFormat("[POS-MODIFY-FAIL] Broker Code:%u(%s), SysErr:%d. Original Params: [Ticket:%I64u, SL:%.5f, TP:%.5f]", 
                                            retCode, retMsg, sysErr, ticket, sl, tp));
            ResetLastError();
            return false;
        }

        // 2. 재확인
        if(PositionSelectByTicket(ticket)) {
            double currentSL = PositionGetDouble(POSITION_SL);
            double currentTP = PositionGetDouble(POSITION_TP);

            if(MathAbs(currentSL - sl) < _Point * 10 && MathAbs(currentTP - tp) < _Point * 10) {
                XP_LOG_OK(NULL, StringFormat("[POS-MODIFY] SUCCESS: Ticket %I64u Modified.", ticket));
                return true;
            }
        }

        XP_LOG_ERROR(NULL, StringFormat("[POS-MODIFY-FAIL] VERIFY FAILED: Modification sent but values not reflected for ticket:%I64u", ticket));
        return false;
    }

    void Reset() {
        m_ticket = 0;
    }
};

