           !guard.ValidatePrice(sig.GetSymbol(), sig.GetPriceSignal())) {

            if(isStatusChanged && IS_VALID(log)) {
                string err = StringFormat("[WATCHER-VALIDATION] FAILED [%s] - %s", sigInfo, guard.GetLastError());
                log.Error(xp, err);
