            sig.SetLastStatus(sig.GetStatus());
            activeList.Delete(i);
            failed++;
        } else {
            if(isStatusChanged && IS_VALID(log)) log.Debug(xp, StringFormat("[WATCHER-VALIDATION] PASSED [%s]", sigInfo));
            sig.SetLastStatus(sig.GetStatus());
        }
    }
}

