    IXGuard*            guard; 
    int                 if_true;
    int                 if_false;
    int                 timeout_sec;
    int                 max_retries;
    int                 current_retries;
    CHashMap<int, int>* branches;

    CXStepNode(IXStep* s, int t_path, int f_path, int timeout = 0, int retries = 0, IXGuard* g = NULL) 
