    CXStepNode(IXStep* s, int t_path, int f_path, int timeout = 0, int retries = 0, IXGuard* g = NULL) 
        : step(s), if_true(t_path), if_false(f_path), 
          timeout_sec(timeout), max_retries(retries), current_retries(0), guard(g) {
