        //-- 1. 진입 파이프라인 (Entry Pipeline) - Hyper-Atomized (L -> G -> G -> P -> R -> V -> V -> V -> V -> P)
        CXCompositeStep* entryStep = new CXCompositeStep("Step_EntryComposite");
        entryStep.AddTask(new CXTaskEntry_L_Validate())
                 .AddTask(new CXTaskGuard_V_Spread())
                 .AddTask(new CXTaskGuard_V_Volatility())
                 .AddTask(new CXTaskEntry_P_Lock())
                 .AddTask(new CXTaskEntry_R_Order())
                 .AddTask(new CXTaskEntry_V_Error())
                 .AddTask(new CXTaskEntry_V_Ticket())
                 .AddTask(new CXTaskEntry_V_Real())
                 .AddTask(new CXTaskFinalize_V_DoubleCheck())
                 .AddTask(new CXTaskEntry_P_Finalize());
        XP_LOG_TRACE(GetPointer(xp), " -> Added: Entry Pipeline (L-G-G-P-R-V-V-V-V-P)");

        seq.From(SESSION_READY).Execute(entryStep)
           .OnSuccess(STATE_ENTRY_TRAILING)
           .OnFail(SESSION_ERROR)
           .Case(SESSION_ACTIVE, SESSION_ACTIVE)
           .Case(SESSION_LIQUIDATING, SESSION_LIQUIDATING)
           .Timeout(300);

