        CXCompositeStep* exitStep = new CXCompositeStep("Step_ExitComposite");
        exitStep.AddTask(new CXTaskExit_L_Prepare())
                .AddTask(new CXTaskExit_P_Lock())
                .AddTask(new CXTaskExit_R_Order())
                .AddTask(new CXTaskExit_V_Error())
                .AddTask(new CXTaskExit_V_Terminal())
                .AddTask(new CXTaskExit_P_Finalize());
        XP_LOG_TRACE(GetPointer(xp), " -> Added: Liquidation Pipeline (L -> P -> R -> V -> V -> P)");

        seq.From(SESSION_LIQUIDATING).Execute(exitStep)
           .OnSuccess(SESSION_CLOSED)
           .OnFail(SESSION_ERROR)
           .Timeout(300)
           .Retries(3);

