                m_isActive = false; // 세션 영구 비활성화 (좀비 방지)
            }
        }
    }

    void Start(ICXParam* xp, ICXServiceFactory* factory) {
        m_isActive = true;
        m_signal = (IS_VALID(xp)) ? xp.GetSignal() : NULL;
